function render(){syncLedger(); $('#pool').textContent=state.pool.toFixed(3);$('#paid').textContent=state.paid.toFixed(3)+' BNB';$('#dealCount').textContent=state.deals;$('#queueCount').textContent=state.queue.length+state.active.filter(Boolean).length;const q=[...state.active.filter(Boolean),...state.queue];$('#queue').innerHTML=q.length?q.map((v,i)=>`<div class="queue-row ${state.active.includes(v)?'active':''}"><div class="portrait sprite s${v.skin}"></div><div><em>${v.status||(state.active.includes(v)?'正在柜台':`等候 ${i+1}`)}</em><br><b>${v.wallet}</b><small>${v.lane+1}号台 · ${v.item.icon} ${v.item.name}</small></div></div>`).join(''):'<div class="empty">柜台空闲。<br>下一件奇物会是什么？</div>';$('#feed').innerHTML=state.history.length?state.history.filter(h=>h.win).slice(0,4).map(h=>`<div class="feed-row"><span class="item-icon">${h.item.icon}</span><div><span>${h.wallet}</span><br><b>+${h.amount.toFixed(4)} BNB</b><small>${h.item.name} · 本次体验</small></div></div>`).join('')||'<div class="empty">暂时还没有成交。<br>下一件或许有惊喜。</div>':'<div class="empty">柜台刚刚开门。<br>带一件奇物进来吧。</div>';$$('.join').forEach(b=>{b.disabled=false;b.textContent='模拟买入 0.05 BNB'});renderPipeline();$('#myState').textContent=state.active.some(v=>v?.mine)?('当前：'+state.active.find(v=>v?.mine).status):state.queue.some(x=>x.mine)?'你已入场，正在排队。':state.visits?'本轮已结束，可以再带一件奇物。':'准备好你的第一件奇物。';}
function createVisitor(mine=false,event=null){counter++;const item={name:'神秘奇物',icon:'🎁',rarity:'待揭晓',chance:0,share:0};const v={id:counter,mine,item,skin:3+(counter%3),wallet:mine?'你 · 0x7A…42F1':`0x${(0x8f21+counter*721).toString(16).toUpperCase()}…${(0x32f0+counter*131).toString(16).toUpperCase()}`};if(event){v.event=event;v.entry=event.entry;v.wallet=escapeText(event.wallet);if(v.entry){v.id=v.entry.id;v.item=v.entry.item||v.item;}v.status='自动排队';event.visitId=v.id;}const el=document.createElement('div');el.className='visitor walking';el.style.left='50%';el.style.top='102%';el.innerHTML=`<span class="wallet">${mine?'你':v.wallet}</span><div class="sprite s${v.skin}"></div><span class="held">${v.item.icon}</span>`;$('#visitors').append(el);v.el=el;const loads=[0,1,2].map(l=>state.queue.filter(q=>q.lane===l).length+(state.active[l]?1:0));v.lane=Number.isInteger(v.entry.lane)?v.entry.lane:loads.indexOf(Math.min(...loads));v.entry.lane=v.lane;persist();Shop3D.add(v);state.queue.push(v);log(`${mine?'你':v.wallet} 带着${item.name}入场`);arrange();render();setTimeout(next,1300);return v}
