function station(lane,text,progress=0){const el=stationPanel.children[lane];el.querySelector('span').textContent=text;el.querySelector('progress').value=progress;el.dataset.busy=state.active[lane]?'true':'false';$('#sceneStatus').textContent=state.active.filter(Boolean).length+' / 3 个柜台正在接待';}
