function chime(win){try{const ac=new (window.AudioContext||window.webkitAudioContext)();[win?523:330,win?659:294].forEach((freq,i)=>{const o=ac.createOscillator(),g=ac.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.06,ac.currentTime+i*.12);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+i*.12+.25);o.connect(g);g.connect(ac.destination);o.start(ac.currentTime+i*.12);o.stop(ac.currentTime+i*.12+.26)});setTimeout(()=>ac.close(),700)}catch{}}
